"devDependencies": {
  "tap": "^21.0.0",
  "tmp": "^0.2.1"
},
"homepage": "https://github.com/irae/mendel#readme",

  "shasum": "^1.0.2",
  "through2": "^5.0.11",
  "tmp": "^0.2.7"
},
"devDependencies": {

"devDependencies": {
  "tap": "^21.0.0",
  "tmp": "^0.2.1"
},
"homepage": "https://github.com/irae/mendel#readme",

/* Copyright 2015, Yahoo Inc.
   Copyrights licensed under the MIT License.
   See the accompanying LICENSE file for terms. */

var nodePath = require('path');
var shasum = require('shasum');
var through = require('through2');
var variationMatches = require('./variation-matches');
var mendelifyRequireTransform = require('./mendelify-require-transform');

function mendelifyTransformStream(variations, bundle) {
    var externals = bundle._external;
    return through.obj(function mendelify(row, enc, next) {
        var avoidMendelifyRow = avoidMendelify(row.file);
        if (!avoidMendelifyRow) {
            var match = variationMatches(variations, row.file);
            if (match) {
                // Remove variations of externals from bundle
                if (someArrayItemEndsWith(externals, match.file)) {
                    return next();
                }
                // accept file and trasform for variation
                row.id = match.file;
                row.variation = match.dir;
            }
        }

        row.id = relativePath(row.id, bundle);

        if (typeof row.expose === 'string') {
            row.expose = relativePath(
                pathOrVariationMatch(row.expose, variations),
                bundle
            );
        }

        Object.keys(row.deps).forEach(function (key) {
            var value = row.deps[key];
            delete row.deps[key];

            var newKey = key;
            var newValue = value;

            if (!avoidMendelify(value) || shouldExternalize(externals, key)) {
                newKey = keyValue(key, variations, bundle);
            }

            newValue = depsValue(value, newKey, variations, bundle);
            row.deps[newKey] = relativePath(newValue, bundle);
        });

        row.rawSource = row.source;
        if (!avoidMendelifyRow) {
            row.source = mendelifyRequireTransform(
                row.file,
                row.source,
                function (requirePath) {
                    return keyValue(requirePath, variations, bundle);
                }
            );
        }
        row.sha = shasum(row.source);

        this.push(row);
        next();
    });
}

function keyValue(key, variations, bundle) {
    return relativePath(pathOrVariationMatch(key, variations), bundle);
}

function avoidMendelify(file) {
    var isExternal = file === false;
    var isNodeModule = -1 !== (file || '').indexOf('node_modules');

    return isExternal || isNodeModule;
}

function pathOrVariationMatch(path, variations) {
    var match = variationMatches(variations, path);
    if (match) {
        return match.file;
    }
    return path;
}

function relativePath(filePath, bundle) {
    var basedir = bundle._options.basedir;
    var result = filePath;
    if (typeof filePath === 'string' && filePath.indexOf(basedir) !== -1) {
        result = nodePath.relative(basedir, filePath);
    }
    return relativeToNodeModules(result);
}

function relativeToNodeModules(filePath) {
    if (typeof filePath === 'string') {
        var index = filePath.indexOf('node_modules/');
        if (index >= 0) {
            return filePath.slice(index);
        }
    }
    return filePath;
}

function depsValue(path, matchFile, variations, bundle) {
    if (typeof path !== 'string') {
        return path;
    }
    var expose = bundle._expose;
    var externals = bundle._external;

    var exposedModule = exposeKey(expose, path);
    if (exposedModule) {
        return pathOrVariationMatch(exposedModule, variations);
    }

    // remove externals from deps
    if (shouldExternalize(externals, matchFile)) {
        return false;
    }

    return pathOrVariationMatch(path, variations);
}

function shouldExternalize(externals, file) {
    return someArrayItemEndsWith(externals, file);
}

function someArrayItemEndsWith(stringArray, partialString) {
    for (var i = 0; i < stringArray.length; i++) {
        var position = stringArray[i].indexOf(partialString);
        if (
            position >= 0 &&
            position === stringArray[i].length - partialString.length
        ) {
            return true;
        }
    }
    return false;
}

function exposeKey(expose, file) {
    var exposedModule = false;
    Object.keys(expose).forEach(function (key) {
        var value = expose[key];
        if (file === value) {
            exposedModule = key;
        }
    });
    return exposedModule;
}

module.exports = mendelifyTransformStream;

const debug = require('debug')('mendel:outlet:manifest');
const babelCore = require('@babel/core');
const manifestUglify = require('mendel-manifest-uglify');
const fs = require('fs');
const shasum = require('shasum');
const inliner = require('babel-plugin-transform-inline-environment-variables');

// Manifest
module.exports = class ManifestOutlet {
    constructor(config, options) {
        // Mendel config
        this.config = config;
        // outlet options
        this.options = Object.assign(
            {
                envify: true,
                uglify: true,
                runtime: 'browser',
            },
            options
        );
        this.runtime = this.options.runtime;
    }

    perform({ entries, options }) {
        debug({ perBundleOptions: options });
        const manifestFileName = options.manifest;
        let envify = this.options.envify;
        let uglify = this.options.uglify;
        if (options.options) {
            if (typeof options.options.envify !== 'undefined') {
                envify = options.options.envify;
            }
            if (typeof options.options.uglify !== 'undefined') {
                uglify = options.options.uglify;
            }
        }

        // We are going to mutate this guy; make sure we don't change the original one
        entries = new Map(entries.entries());
        if (envify) this.removeProcess(entries);
        let manifest = this.getV1Manifest(entries);

        if (envify) manifest = this.envify(manifest);
        if (uglify) manifest = this.uglify(manifest);

        fs.writeFileSync(manifestFileName, JSON.stringify(manifest, null, 2));

        debug(`Outputted: ${manifestFileName}`);
    }

    dataFromItem(item) {
        const deps = {};
        Object.keys(item.deps).forEach((key) => {
            const dep = item.deps[key][this.runtime];
            deps[key] = dep;
        });

        const data = {
            id: item.normalizedId,
            deps,
            file: item.id,
            variation: item.variation || this.config.baseConfig.dir,
            source: item.source,
            sha: shasum(item.source),
        };

        if (item.expose) data.expose = item.expose;
        if (item.entry) data.entry = item.entry;
        if (item.order) data.order = item.order;
        return data;
    }

    removeProcess(entries) {
        Array.from(entries.keys()).forEach((key) => {
            const entry = entries.get(key);
            if (!entry) return;

            if (entry.normalizedId === 'process') entries.delete(key);
        });
    }

    envify(manifest) {
        manifest.bundles.map((row) => {
            row.data.forEach((data) => {
                if (!data.deps.process) return;

                const { code } = babelCore.transform(data.source, {
                    filename: data.id,
                    plugins: [inliner],
                });
                data.source = code;
                delete data.deps.process;
            });
        });

        return manifest;
    }

    uglify(manifest) {
        manifestUglify(
            [manifest],
            {
                // `compress` and `mangle` are set to `true` on uglifyify
                // just making sure we have the same defaults
                uglifyOptions: {
                    root: this.config.baseConfig.dir,
                    compress: this.options.compress
                        ? this.options.compress
                        : true,
                    mangle: this.options.mangle ? this.options.mangle : true,
                },
            },
            ([uglifiedManifest]) => {
                // happens immediately
                manifest = uglifiedManifest;
            }
        );

        return manifest;
    }

    getV1Manifest(entries) {
        const manifest = {
            indexes: {},
            bundles: [],
        };

        const errors = [];

        Array.from(entries.keys())
            .sort()
            .forEach((key) => {
                const item = entries.get(key);
                const id = item.normalizedId;

                try {
                    if (
                        !Object.getOwnPropertyDescriptor(manifest.indexes, id)
                    ) {
                        const data = this.dataFromItem(item);
                        const newEntry = {
                            id: item.normalizedId,
                            index: null,
                            variations: [data.variation],
                            data: [data],
                        };

                        if (data.entry) newEntry.entry = data.entry;
                        if (data.expose) newEntry.expose = data.expose;
                        manifest.bundles.push(newEntry);
                        const index = manifest.bundles.indexOf(newEntry);

                        manifest.indexes[id] = index;
                        newEntry.index = index;
                    } else {
                        const index = manifest.indexes[id];
                        const existing = manifest.bundles[index];
                        const newData = this.dataFromItem(item);
                        if (existing.variations.includes(newData.variation)) {
                            return debug(
                                `${existing.file}|${existing.variations}  `,
                                `${item.id}|${item.variation}`,
                                'WARN: normalizedId and variation collision'
                            );
                        }
                        existing.variations.push(newData.variation);
                        existing.data.push(newData);

                        if (newData.entry) existing.entry = newData.entry;
                        if (newData.expose) existing.expose = newData.expose;
                    }
                } catch (e) {
                    e.item = { id: item.id, normalizedId: item.normalizedId };
                    errors.push(e);
                }
            });

        if (errors.length > 0) {
            throw errors;
        }

        return manifest;
    }
};

